INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 12, 'theory', 'Quiz: GROUP BY and HAVING');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 0, 'How does HAVING differ from WHERE?', '["It doesn''t, they are synonyms", "WHERE filters rows before grouping, HAVING filters groups by aggregates after it", "HAVING works only with text", "WHERE runs after GROUP BY"]', 1, 'WHERE runs before grouping and does not see aggregates; HAVING runs after it, and its condition can use COUNT, SUM and other aggregates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 1, 'Which columns may be selected in a query with GROUP BY status?', '["Any columns of the table", "status and aggregate functions", "Only aggregate functions", "Only columns with unique values"]', 1, 'SELECT may contain grouping keys and aggregates. Other columns have no single value for a group (SQLite returns an arbitrary one, but that is wrong).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 2, 'How do NULLs behave in a GROUP BY key?', '["They are dropped", "They form one separate group", "Each NULL is its own group", "They cause an error"]', 1, 'For grouping, all NULLs are considered equal and fall into one group.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 3, 'What is the correct order of execution of the parts of a query?', '["SELECT → FROM → WHERE → GROUP BY → HAVING", "FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT", "FROM → GROUP BY → WHERE → HAVING → SELECT", "WHERE → FROM → SELECT → GROUP BY"]', 1, 'This order explains why aggregates and aliases cannot be used in WHERE, but can be used in ORDER BY.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 12, 4, 'Why is it better to group customer totals by id rather than by name?', '["id is shorter", "Different customers may have the same name and would merge into one group", "name cannot be used in GROUP BY", "id sorts faster"]', 1, 'A group key must identify the entity unambiguously. Names can coincide; the id is unique.');
